(()=>{'use strict';const reader=document.querySelector('#webtoon-reader'),opener=document.querySelector('#open-webtoon');opener.onclick=()=>{reader.showModal();document.body.classList.add('comic-open')};for(const id of ['close-webtoon','finish-webtoon'])document.getElementById(id).onclick=()=>reader.close();reader.addEventListener('close',()=>{document.body.classList.remove('comic-open');opener.focus({preventScroll:true})});reader.addEventListener('click',e=>{if(e.target!==reader)return;const r=reader.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)reader.close()});let enabled=true,context,last=0;try{enabled=localStorage.getItem('daeyeok-sfx')!=='off'}catch{}const toggle=document.querySelector('#sfx-toggle');function render(){toggle.textContent=enabled?'효과음 켜짐':'효과음 꺼짐';toggle.setAttribute('aria-pressed',String(enabled));toggle.setAttribute('aria-label',enabled?'효과음 끄기':'효과음 켜기')}render();toggle.onclick=()=>{enabled=!enabled;try{localStorage.setItem('daeyeok-sfx',enabled?'on':'off')}catch{}render()};function play(){if(!enabled||performance.now()-last<65)return;last=performance.now();try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;context??=new Audio();if(context.state==='suspended')context.resume().catch(()=>{});const t=context.currentTime,osc=context.createOscillator(),gain=context.createGain();osc.type='sine';osc.frequency.setValueAtTime(880,t);osc.frequency.exponentialRampToValueAtTime(440,t+.055);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.035,t+.004);gain.gain.exponentialRampToValueAtTime(.0001,t+.075);osc.connect(gain);gain.connect(context.destination);osc.start(t);osc.stop(t+.08);osc.onended=()=>{osc.disconnect();gain.disconnect()}}catch{}}document.addEventListener('click',e=>{const b=e.target.closest('button,a[href],[role="button"]');if(!b||b.disabled||b.getAttribute('aria-disabled')==='true')return;play()});})();
